cypress_script:
describe('File Upload and Download Tests', () => {
  it('should upload a file successfully', () => {
    cy.visit('https://demoqa.com/upload-download');
    const filePath = 'path/to/your/file.txt'; // Adjust the path to your test file
    cy.get('#uploadFile').attachFile(filePath);
    // Add assertions here if needed, but we focus on the upload functionality
  });

  it('should not change the URL when no file is uploaded', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#uploadFile').should('exist');
    // Assert that the URL is still the same after attempting to upload without a file
    cy.url().should('eq', 'https://demoqa.com/upload-download');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload and Download Tests', () => {
  test('should upload a file successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    const filePath = 'path/to/your/file.txt'; // Adjust the path to your test file
    await page.setInputFiles('#uploadFile', filePath);
    // Add assertions here if needed, but we focus on the upload functionality
  });

  test('should not change the URL when no file is uploaded', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    await expect(page.locator('#uploadFile')).toBeVisible();
    // Assert that the URL is still the same after attempting to upload without a file
    await expect(page).toHaveURL('https://demoqa.com/upload-download');
  });
});
